{
  "lines": [
    {
      "text": "Ausz dem Haushaltungsbuche, 1786"
    },
    {
      "text": "Den 12. Junius. Für die Post von Leublau bis Liegnitz 2 Thaler 8 Groschen."
    },
    {
      "text": "Den 14. Junius. Zum Wirth in Liegnitz für Nachtlager und Hau 1 Thaler 12 Groschen. Für freie"
    },
    {
      "text": "Brüge 3 Thaler."
    },
    {
      "text": "Den 19. Junius. In Breslau, Gasthof zum goldenen Engel, darzu Näpfe 6 Thaler."
    },
    {
      "text": "Den 2. Julius. Berlin. Zum Kaufmann Itzig für Defung 4 Thaler."
    },
    {
      "text": "Den 22. Julius. Danzig. Für die Unterfahrt nach Elbing 1 Thaler 4 Groschen."
    },
    {
      "text": "Summa bis Danzig: 47 Thaler 18 Groschen."
    }
  ],
  "script": "kurrent",
  "notes": "Handwritten in Kurrent script. Some letters (e.g. 's', 'f', 't') have characteristic cursive forms. 'Thaler' and 'Groschen' are currency units. Line breaks follow the original."
}

